insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-001','assets/audio/heygen-part3/conversation-01.wav','e046e1fed1a52eedfdacdc1402ec809880b76907606985dde353a9748f581a17',10.999,'{"turns":[{"role":"female","start":0,"end":3.326},{"role":"male","start":3.506,"end":5.353},{"role":"female","start":5.533,"end":8.873},{"role":"male","start":9.053,"end":10.999}],"transcript":"Woman: I booked the meeting room for ten, but the projector is not working. Man: I can ask the technician to take a look. Woman: Thanks. If it cannot be fixed, we can move to room six. Man: I will let you know before nine thirty.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-002','assets/audio/heygen-part3/conversation-02.wav','b305c242c7c2c7727c2c9ce4330b6a7790f698cc3aa4548e413453e22cb59e2a',13.063,'{"turns":[{"role":"male","start":0,"end":4.279},{"role":"female","start":4.459,"end":10.24},{"role":"male","start":10.42,"end":13.063}],"transcript":"Man: Hello. I ordered twenty office chairs last week, but only fifteen arrived. Woman: I am sorry. The remaining five are at our warehouse. We can deliver them on Thursday at no extra charge. Man: Thursday works, as long as they arrive before noon.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-003','assets/audio/heygen-part3/conversation-03.wav','0155b116320fbfc3d50e2d4da239f6426eb4fa092e29787ca6ea55803a889f63',12.038916666666667,'{"turns":[{"role":"female","start":0,"end":2.245},{"role":"male","start":2.425,"end":4.715},{"role":"female","start":4.895,"end":8.717958333333334},{"role":"male","start":8.897958333333333,"end":12.038916666666667}],"transcript":"Woman: Have you tried the new cafe across from the station? Man: Not yet. Does it have vegetarian options? Woman: Yes, and it is offering a discount this week. Shall we go there for lunch? Man: Good idea. I finish my client call at twelve fifteen.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-004','assets/audio/heygen-part3/conversation-04.wav','c6de865d9fd3238410c2d0583c034a4ee9fa555924d04aba098b6ee0ee62153f',15.550958333333334,'{"turns":[{"role":"female","start":0,"end":3.9879583333333333},{"role":"male","start":4.167958333333333,"end":8.062958333333333},{"role":"female","start":8.242958333333334,"end":12.208958333333333},{"role":"male","start":12.388958333333333,"end":15.550958333333334}],"transcript":"Woman: We are almost out of printer paper. Should I order our usual ten boxes? Man: Make it fifteen this time. The training team needs extra copies next month. Woman: The supplier offers free delivery for orders of twelve boxes or more. Man: Great. Please place the order before lunch so it arrives tomorrow.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-005','assets/audio/heygen-part3/conversation-05.wav','0f1740ef404182a52317fcd1a86d908d9f28fda98d36700ec5e699a7a230736e',17.431958333333334,'{"turns":[{"role":"male","start":0,"end":5.757},{"role":"female","start":5.937,"end":11.955958333333333},{"role":"male","start":12.135958333333333,"end":14.949958333333333},{"role":"female","start":15.129958333333333,"end":17.431958333333334}],"transcript":"Man: My flight lands at six, but the conference dinner begins at seven. Will I have time to check in at the hotel? Woman: The airport shuttle takes forty minutes. You should go straight to the restaurant. I can ask the hotel to hold your room. Man: Thank you. Can I leave my suitcase at the restaurant? Woman: Yes, they have a cloakroom near the entrance.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-006','assets/audio/heygen-part3/conversation-06.wav','b2459778898db1bb4dae16f67eb5af81fb363702f5841e27340dd47c44798ee3',17.432,'{"turns":[{"role":"male","start":0,"end":3.4860416666666665},{"role":"female","start":3.6660416666666666,"end":7.290041666666666},{"role":"male","start":7.470041666666667,"end":10.426},{"role":"female","start":10.606,"end":14.993},{"role":"male","start":15.173,"end":17.432}],"transcript":"Customer: I bought these headphones yesterday, but the left side has no sound. Assistant: I am sorry about that. Would you like a refund or a replacement? Customer: A replacement, please. I need them for a trip tomorrow. Assistant: We have the same model in black, but the blue version will not arrive until Friday. Customer: Black is fine. Here is my receipt.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-007','assets/audio/heygen-part3/conversation-07.wav','2a903646fa13dcd6eb95deedba8269392fca68f1cf409f52db2e50ed9e12ad80',16.827083333333334,'{"turns":[{"role":"female","start":0,"end":3.8950416666666667},{"role":"male","start":4.0750416666666665,"end":7.4290416666666665},{"role":"female","start":7.609041666666666,"end":9.769041666666666},{"role":"male","start":9.949041666666666,"end":13.435083333333333},{"role":"female","start":13.615083333333333,"end":16.827083333333334}],"transcript":"Woman: We have forty-eight registrations, but room two seats only forty. Man: Room five holds sixty, and it is free that afternoon. Woman: Perfect. Does it have microphones? Man: Yes, but we need to request them from the events team by Wednesday. Woman: I will email them now and update the room number on the invitations.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-008','assets/audio/heygen-part3/conversation-08.wav','c8d5f27e068870947f375b9176edd71e46cb18569ebd0c07f88f80a61f89a0aa',16.565,'{"turns":[{"role":"male","start":0,"end":3.113},{"role":"female","start":3.293,"end":6.566},{"role":"male","start":6.746,"end":10.257},{"role":"female","start":10.437,"end":16.565}],"transcript":"Man: The interview with Ms. Sato is set for Thursday at eleven. Woman: I have a client visit then. Could we move it to one thirty? Man: She said she is available after lunch. I will call her to confirm. Woman: Thanks. Please also send her the updated job description. We have added responsibility for the monthly newsletter.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-009','assets/audio/heygen-part3/conversation-09.wav','eb951f1c6805ec23df584c70818055b072a87c121d6cccebb830b3213b8eb9ae',17.260958333333335,'{"turns":[{"role":"female","start":0,"end":3.169958333333333},{"role":"male","start":3.3499583333333334,"end":5.3529583333333335},{"role":"female","start":5.532958333333333,"end":8.550958333333334},{"role":"male","start":8.730958333333334,"end":14.721958333333333},{"role":"female","start":14.901958333333333,"end":17.260958333333335}],"transcript":"Woman: The glass containers arrived, but two cartons are damaged. Man: Did you take photos before unpacking them? Woman: Yes. I also noted the damage on the delivery form. Man: Good. Send the photos and form to the supplier. They said they can send replacements within three working days. Woman: I will do that before I update the inventory.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-010','assets/audio/heygen-part3/conversation-10.wav','c6cbda3d7fbe254c80dc6a2d9e283e2ee6555cc514465f54adf35d5c05b27ef8',18.860125,'{"turns":[{"role":"female","start":0,"end":2.5860416666666666},{"role":"male","start":2.7660416666666667,"end":8.083041666666666},{"role":"female","start":8.263041666666666,"end":10.025083333333333},{"role":"male","start":10.205083333333333,"end":15.582125},{"role":"female","start":15.762125,"end":18.860125}],"transcript":"Woman: My reimbursement is lower than the amount I claimed. Man: Let me check. Your hotel and train expenses were approved, but the taxi receipt is missing. Woman: I uploaded it separately this morning. Man: That was after yesterday’s processing deadline. We will include the taxi fare in next Friday’s payment. Woman: All right. I will keep the original receipt until then.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-011','assets/audio/heygen-part3/conversation-11.wav','d2d5c7c726fd84f1e53cffe990e0f347e09b2a999d1960f528615f66a77ee2fb',17.278083333333335,'{"turns":[{"role":"male","start":0,"end":2.487041666666667},{"role":"female","start":2.6670416666666665,"end":4.065083333333333},{"role":"male","start":4.2450833333333335,"end":5.779083333333333},{"role":"female","start":5.959083333333333,"end":13.367083333333333},{"role":"male","start":13.547083333333333,"end":15.166083333333333},{"role":"female","start":15.346083333333333,"end":17.278083333333335}],"transcript":"Man: The booking app keeps closing when I try to add a room. Woman: Which version are you using? Man: Version four point one. Woman: That issue was fixed in four point two. Please update the app first. If it still happens, send me a screenshot of the error message. Man: Will I lose my existing bookings? Woman: No, they are saved on the server.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-012','assets/audio/heygen-part3/conversation-12.wav','3b3b224ebda410622f76ec7648906e6611b6d255705600c1e2df4c5d76952906',17.834,'{"turns":[{"role":"female","start":0,"end":3.246},{"role":"male","start":3.426,"end":8.697},{"role":"female","start":8.877,"end":10.823},{"role":"male","start":11.003,"end":15.281},{"role":"female","start":15.461,"end":17.834}],"transcript":"Woman: Our floor is too warm again. Have you heard from Facilities? Man: A technician checked the air conditioner this morning. It needs a replacement part that arrives on Tuesday. Woman: We have a client presentation on Monday. Man: Room eight on the ground floor has working air conditioning. I can reserve it for you. Woman: Please do. We need it from ten to noon.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
insert into public.audio_assets(id,storage_path,sha256,duration,metadata) values('part3-013','assets/audio/heygen-part3/conversation-13.wav','4e3c8451a490299ebb3fcba8131bd35ef607a6cfb070294cbaf8a0c3c5135b37',18.724,'{"turns":[{"role":"male","start":0,"end":4.413},{"role":"female","start":4.593,"end":7.421},{"role":"male","start":7.601,"end":11.454},{"role":"female","start":11.634,"end":15.213},{"role":"male","start":15.393,"end":18.724}],"transcript":"Man: The brochure is ready, but I noticed the old support number is still on the back page. Woman: Thank you for catching that. Have we sent the file to the printer? Man: Not yet. They need it by four to deliver the brochures on Friday. Woman: I will correct the number now. Could you check the website address as well? Man: Certainly. I will send the final file after your correction.","qa_status":"not-listened"}'::jsonb) on conflict do nothing;
