insert into public.questions(id,content_version,group_id,part,prompt,options,skill_tags,metadata_status) values(23,'3f4003573b740ed5','group-023',5,'All employees must submit their travel expenses _____ Friday.','["by","until","during","since"]'::jsonb,array['deadline-preposition'],'reviewed') on conflict do nothing;
